// Shared by the iPhone app's generators: where the repository is, writing a generated file or,
// with --check, failing when the committed one differs, and a few Swift literal helpers.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

/** The repository root. */
export const root = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");

/** True when the script runs as a check: it writes nothing and fails on any drift. */
export const checking = process.argv.includes("--check");

const stale = [];
let written = 0;

/** A path under the repository, from its parts. */
export function repo(...parts) {
  return join(root, ...parts);
}

/**
 * Writes `contents` (a string or bytes) to `path`, or with --check records that the committed
 * file differs. `same` compares the committed bytes with the new ones when exact bytes are not
 * the test (rasterised images).
 */
export function emit(path, contents, same = (a, b) => a.equals(b)) {
  const bytes = typeof contents === "string" ? Buffer.from(contents, "utf8") : contents;
  const current = existsSync(path) ? readFileSync(path) : null;
  const unchanged = current !== null && same(current, bytes);
  if (checking) {
    if (!unchanged) stale.push(relative(root, path));
    return;
  }
  if (unchanged) return;
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, bytes);
  written += 1;
  console.log(`wrote ${relative(root, path)}`);
}

/** Ends a generator: under --check, fails naming each stale file and the command that fixes it. */
export function finish(command) {
  if (checking) {
    if (stale.length > 0) {
      for (const file of stale) console.error(`${file} is out of date.`);
      console.error(`Run \`${command}\` and commit the result.`);
      process.exitCode = 1;
    } else {
      console.log(`${command}: up to date.`);
    }
  } else if (written === 0) {
    console.log(`${command}: nothing changed.`);
  }
}

/**
 * esbuild, as Vite depends on it: the desktop's Vite resolves it, so the version is the one the
 * lockfile pins and nothing new is installed.
 */
export function loadEsbuild() {
  const vite = createRequire(repo("apps/desktop/package.json")).resolve("vite/package.json");
  return createRequire(vite)("esbuild");
}

/** A Swift string literal for `text`: printable ASCII as is, everything else escaped. */
export function swiftString(text) {
  let out = '"';
  for (const char of text) {
    const code = char.codePointAt(0) ?? 0;
    if (char === '"' || char === "\\") out += `\\${char}`;
    else if (char === "\n") out += "\\n";
    else if (char === "\r") out += "\\r";
    else if (char === "\t") out += "\\t";
    else if (code >= 0x20 && code < 0x7f) out += char;
    else out += `\\u{${code.toString(16)}}`;
  }
  return `${out}"`;
}

/**
 * A Swift multi-line raw string literal holding `text`, with enough `#` that nothing inside can
 * end it. Used for JSON the tests decode.
 */
export function swiftRawString(text) {
  let hashes = 1;
  while (text.includes(`"${"#".repeat(hashes)}`)) hashes += 1;
  const fence = "#".repeat(hashes);
  return `${fence}"""\n${text}\n"""${fence}`;
}

/** A number as Swift source: integers bare, others as the shortest round-tripping decimal. */
export function swiftNumber(value) {
  if (!Number.isFinite(value)) throw new Error(`not a finite number: ${value}`);
  return Object.is(value, -0) ? "0" : String(value);
}

/** The header every generated Swift file starts with. */
export function swiftHeader(script, sources, check) {
  return [
    `// Generated by \`${script}\` from ${sources}.`,
    `// Do not edit: change the sources and run it again. \`${check}\` fails when this file drifts.`,
    "",
  ].join("\n");
}
